/* Dashboard, ConnectBox, Settings, Member profile, Admin panel */
(function () {
  const { I, esc, av, member, hero, tabs, sectionHead, card, empty, seg, bar, statCard, modal, toast, register, ACTS, MENUS, D } = P;

  /* ───────────── Dashboard ───────────── */
  const DTABS = [
    { id: 'quickstats', label: 'Quick Stats', icon: 'chart-column' }, { id: 'routine', label: 'Routine', icon: 'calendar-days' },
    { id: 'calendar', label: 'Semester View', icon: 'calendar' }, { id: 'exams', label: 'Zero Hour', icon: 'book-open' },
    { id: 'attendance', label: 'Attendance', icon: 'list-checks' }, { id: 'notices', label: 'Notice Board', icon: 'megaphone' },
  ];
  const noticeRow = (n) => `<div class="swipe"><div class="swipe-bg"><span class="l">${I('trash-2', 15)}Delete</span><span class="r">Edit${I('pencil', 15)}</span></div>
    <div class="swipe-fg list-row" data-act="notice" data-id="${n.id}" style="padding:12px 4px">${av(n.by, 36)}<div class="grow"><div class="t">${esc(n.title)}</div><div class="s">${esc(member(n.by).name)} · ${n.time}</div></div><span class="chip amber">${n.tag}</span><button class="icon-btn" data-menu="notice">${I('ellipsis-vertical', 16)}</button></div></div>`;
  ACTS.notice = (el) => { if (el.dataset.dragged) return; const n = D.notices.find((x) => x.id === el.dataset.id); modal({ title: n.title, sub: `${member(n.by).name} · ${n.time}`, icon: 'megaphone', body: `<span class="chip amber" style="align-self:flex-start">${n.tag}</span><p style="margin:0;line-height:1.6" class="muted">${esc(n.body)}</p>`, foot: `<button class="btn" data-close>Close</button><button class="btn primary" data-save data-msg="Saved to bookmarks">${I('bookmark', 15)}Bookmark</button>` }); };
  ACTS['swipe-edit'] = () => addNotice(true);
  function addNotice(edit) {
    modal({ title: edit ? 'Edit notice' : 'Post a notice', sub: 'Visible to your section', icon: 'megaphone', body: `
      <div class="field"><span class="label">Title</span><input class="input" value="${edit ? 'Mid-term routine published for Spring 2026' : ''}" placeholder="What's happening?"></div>
      <div class="form-grid"><div class="field"><span class="label">Tag</span><select class="input"><option>Exam</option><option>Class</option><option>Event</option><option>Campus</option></select></div><div class="field"><span class="label">Audience</span><select class="input"><option>CSE · Batch 2022 · B</option><option>All CSE</option></select></div></div>
      <div class="field"><span class="label">Details</span><textarea class="input" placeholder="Add details…"></textarea></div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-save data-msg="${edit ? 'Notice updated' : 'Notice posted'}">${edit ? 'Update' : 'Post notice'}</button>` });
  }
  ACTS['add-notice'] = () => addNotice(false);
  MENUS.notice = [['pencil', 'Edit', '', 'add-notice'], ['bookmark', 'Bookmark'], ['bell', 'Remind me'], ['trash-2', 'Delete', 'danger']];

  function routineGrid() {
    const r = D.routine; const today = 'Mon';
    return `<div class="tscroll"><table class="table routine"><thead><tr><th>Day</th>${r.slots.map((s) => `<th>${s}</th>`).join('')}</tr></thead><tbody>${r.days.map((d) => {
      let skip = 0;
      return `<tr class="${d === today ? 'today' : ''}"><td style="font-weight:700">${d}${d === today ? ' <span class="chip amber">Today</span>' : ''}</td>${r.slots.map((_, i) => {
        if (skip) { skip--; return ''; }
        const c = r.cells[`${d}-${i}`]; if (!c) return '<td><span class="slot-empty"></span></td>';
        if (c[2]) skip = c[2] - 1;
        return `<td colspan="${c[2] || 1}"><div class="slot ${c[0].includes('Lab') ? 'lab' : ''}" data-act="slot" data-c="${esc(c[0])}" data-r="${c[1]}"><b>${c[0]}</b><span>${c[1]}</span></div></td>`;
      }).join('')}</tr>`;
    }).join('')}</tbody></table></div>`;
  }
  ACTS.slot = (el) => modal({ title: el.dataset.c, sub: 'Room ' + el.dataset.r, icon: 'calendar-days', body: `<div class="g2 grid"><div><span class="label">Teacher</span><div style="font-weight:600;margin-top:4px">Dr. A. K. M. Rahman</div></div><div><span class="label">Attendance</span><div style="font-weight:600;margin-top:4px" class="ok">88%</div></div></div><div class="dashed"></div><div class="field"><span class="label">Note for this class</span><textarea class="input" placeholder="Bring lab manual…"></textarea></div>`, foot: `<button class="btn ghost" data-close>Close</button><button class="btn primary" data-save data-msg="Note saved">Save note</button>` });

  function dashboard(sub) {
    sub = sub || 'quickstats';
    const h = hero({ icon: 'sun', eyebrow: 'Good evening · Wed, 19 Nov', a: 'Welcome back, ', b: 'Mubasshir', sub: 'You have 2 classes tomorrow and 1 deadline due in 24 hours.', side: `<button class="btn" data-go="/dashboard/routine">${I('calendar-days', 15)}Routine</button><button class="btn primary" data-act="add-notice">${I('plus', 15)}Post notice</button>` });
    let body = '';
    if (sub === 'quickstats') body = `
      <div class="grid g4 keep2">${statCard('Current CGPA', '3.62', `<span class="good">${I('trending-up', 13)}+0.07</span> vs last sem`, 'graduation-cap')}${statCard('Avg. Attendance', '86%', 'Above 75% minimum', 'list-checks', 'green')}${statCard('Pending Deadlines', '4', '<span class="bad">1 due tomorrow</span>', 'clock', 'rose')}${statCard('Credits Completed', '98', 'of 160 · 61%', 'award', 'cyan')}</div>
      <div class="main-grid"><div class="stack">${card("Today's classes", 'calendar-days', `<div class="list">${[['8:00', 'CSE 3201', 'Operating Systems', '7A02'], ['9:30', 'CSE 3207', 'Software Engineering', '7A02'], ['12:30', 'MATH 3201', 'Numerical Methods', '6B01']].map(([t, c, n, r], i) => `<div class="list-row"><div style="width:52px" class="num">${t}</div><div class="grow"><div class="t">${c} · ${n}</div><div class="s">Room ${r}</div></div>${i === 0 ? '<span class="chip green">Done</span>' : i === 1 ? '<span class="chip amber">Now</span>' : '<span class="chip">Later</span>'}</div>`).join('')}</div>`, `<a class="btn sm ghost" data-go="/dashboard/routine">Full routine ${I('arrow-right', 13)}</a>`)}
        ${card('Notice Board', 'megaphone', `<div class="list">${D.notices.slice(0, 3).map(noticeRow).join('')}</div><div class="faint" style="font-size:11px;margin-top:8px">Tip: swipe a notice left to edit, right to delete.</div>`, `<a class="btn sm ghost" data-go="/dashboard/notices">See all</a>`)}</div>
        <div class="stack">${card('Deadlines', 'clock', `<div class="list">${D.deadlines.map((d) => `<div class="list-row"><span class="ic-tile ${d.u ? 'rose' : ''}">${I('file-text', 16)}</span><div class="grow"><div class="t">${d.t}</div><div class="s">${d.c}</div></div><span class="chip ${d.u ? 'rose' : ''}">${d.d}</span></div>`).join('')}</div>`, `<button class="icon-btn" data-act="add-deadline">${I('plus', 16)}</button>`)}
        ${card('CGPA trend', 'trending-up', spark(D.semesters.map((s) => s.g)) + `<div class="row between faint" style="font-size:11px;margin-top:6px">${D.semesters.map((s) => `<span>${s.s}</span>`).join('')}</div>`)}</div></div>`;
    else if (sub === 'routine') body = `<div class="content-card">${sectionHead('calendar-days', 'Dashboard', 'Weekly Routine', 'CSE · Year 3 · Semester 2 · Section B', `<button class="btn sm" data-go="/routine-templates">${I('layout-grid', 14)}<span>Templates</span></button><button class="btn sm primary" data-act="toast" data-msg="Routine exported">${I('download', 14)}<span>Export</span></button>`)}${routineGrid()}</div>`;
    else if (sub === 'calendar') body = `<div class="content-card">${sectionHead('calendar', 'Dashboard', 'Semester View', '14-week overview · Spring 2026')}<div class="weeks">${Array.from({ length: 14 }, (_, i) => `<div class="wk ${i === 9 ? 'now' : ''} ${i < 9 ? 'past' : ''}" data-act="toast" data-msg="Week ${i + 1} opened"><span class="label">Week ${i + 1}</span><b>${['', '', '', 'Quiz 1', '', '', 'Mid', 'Mid', '', 'Quiz 2', '', 'Project', '', 'Finals'][i] || '—'}</b></div>`).join('')}</div></div>`;
    else if (sub === 'exams') body = `<div class="content-card">${sectionHead('book-open', 'Zero Hour', 'Exam countdown', 'Quiz, Mid & Final in one place', `<button class="btn sm primary" data-act="add-deadline">${I('plus', 14)}<span>Add exam</span></button>`)}<div class="grid g3">${[['Quiz 2', 'CSE 3201', '4d 06h', 62], ['Mid-term', 'All courses', '18d', 30], ['Final', 'All courses', '52d', 8]].map(([a, b, c, p]) => `<section class="card"><span class="label">${b}</span><h3 style="margin:6px 0 2px">${a}</h3><div class="num" style="font-size:1.8rem" class="ok">${c}</div><div class="faint" style="font-size:11px;margin:6px 0 8px">Prep progress ${p}%</div>${bar(p)}</section>`).join('')}</div></div>`;
    else if (sub === 'attendance') body = `<div class="content-card">${sectionHead('list-checks', 'Dashboard', 'Attendance', 'Semester progress per course')}<div class="list">${D.courses.map((c) => `<div class="list-row"><div class="grow"><div class="t">${c.code} · ${c.name}</div><div style="margin-top:7px">${bar(c.att, c.att < 75 ? 'rose' : '')}</div></div><b class="num ${c.att < 75 ? 'bad' : ''}" style="width:50px;text-align:right">${c.att}%</b><div class="row" style="gap:4px"><button class="btn sm" data-act="toast" data-msg="Marked present">${I('check', 13)}</button><button class="btn sm" data-act="toast" data-msg="Marked absent">${I('x', 13)}</button></div></div>`).join('')}</div></div>`;
    else body = `<div class="content-card">${sectionHead('megaphone', 'Dashboard', 'Notice Board', 'Swipe left to edit · right to delete', `<button class="btn sm primary" data-act="add-notice">${I('plus', 14)}<span>Post</span></button>`)}${seg('ntag', ['All', 'Exam', 'Class', 'Event', 'Campus'], 'All')}<div class="list" style="margin-top:12px">${D.notices.map(noticeRow).join('')}</div></div>`;
    return h + tabs('/dashboard', DTABS, sub) + body;
  }
  function spark(vals) {
    const w = 300, h = 90, min = 3.2, max = 4; const pts = vals.map((v, i) => [i * (w / (vals.length - 1)), h - ((v - min) / (max - min)) * h]);
    return `<svg viewBox="-6 -8 ${w + 12} ${h + 16}" style="width:100%;height:110px"><polyline fill="none" stroke="var(--accent-amber)" stroke-width="2.5" points="${pts.map((p) => p.join(',')).join(' ')}"/>${pts.map(([x, y], i) => `<circle cx="${x}" cy="${y}" r="4" fill="var(--bg-card)" stroke="var(--accent-amber)" stroke-width="2"><title>${vals[i]}</title></circle>`).join('')}</svg>`;
  }
  P.spark = spark;
  ACTS['add-deadline'] = () => modal({ title: 'Add deadline', icon: 'clock', body: `<div class="field"><span class="label">Title</span><input class="input" placeholder="Assignment, quiz…"></div><div class="form-grid"><div class="field"><span class="label">Course</span><select class="input">${D.courses.map((c) => `<option>${c.code}</option>`)}</select></div><div class="field"><span class="label">Due</span><input class="input" type="date" value="2026-11-27"></div></div>`, foot: `<button class="btn ghost" data-close>Cancel</button><button class="btn primary" data-save data-msg="Deadline added">Add</button>` });
  register({ path: '/dashboard', title: 'Dashboard', group: 'Main', icon: 'layout-dashboard', render: dashboard, subs: DTABS.map((t) => t.id) });
  register({ path: '/routine-templates', title: 'Routine Templates', group: 'Main', icon: 'layout-grid', nav: '/dashboard', render: () => P.masthead({ icon: 'layout-grid', over: 'Dashboard', title: 'Routine Templates', sub: 'Pick your section — the routine fills itself', stats: [['Templates', '64'], ['Depts', '8']] }) + `<div class="grid g3">${['CSE 3.2 · A', 'CSE 3.2 · B', 'CSE 3.2 · C', 'EEE 2.1 · A', 'ME 4.1 · B', 'ARCH 3.1 · A'].map((t, i) => `<section class="card hoverable" data-act="toast" data-msg="${t} applied"><div class="row between"><b>${t}</b>${i === 1 ? '<span class="chip amber">Yours</span>' : ''}</div><div class="faint" style="font-size:12px;margin-top:6px">${18 + i} classes · updated ${i + 1}d ago</div></section>`).join('')}</div>` });

  /* ───────────── ConnectBox ───────────── */
  let activeConv = 'c1';
  function connectbox(sub) {
    if (sub) activeConv = sub;
    const c = D.convs.find((x) => x.id === activeConv); const m = member(c.with);
    return `<div class="chat ${sub ? 'in-conv' : ''}">
      <div class="chat-list"><div style="padding:14px 14px 10px" class="row between"><b style="font-size:16px">ConnectBox</b><button class="icon-btn" data-act="new-chat">${I('square-pen', 17)}</button></div>
        <div style="padding:0 14px 12px"><div class="searchbar" style="width:100%" data-act="search">${I('search', 14)}Search chats</div></div>
        <div style="padding:0 14px 10px">${seg('chatf', ['All', 'Unread', 'Groups'], 'All')}</div>
        <div class="scroll">${D.convs.map((x) => `<div class="conv ${x.id === activeConv ? 'on' : ''}" data-go="/connectbox/${x.id}">${av(x.with, 42)}<div style="min-width:0;flex:1"><div class="row between"><span class="t">${member(x.with).name}</span><span class="faint" style="font-size:10.5px">${x.time}</span></div><div class="row between"><span class="p">${esc(x.last)}</span>${x.unread ? `<b class="chip amber" style="height:18px;padding:0 6px">${x.unread}</b>` : ''}</div></div></div>`).join('')}</div></div>
      <div class="chat-main"><div class="chat-top"><button class="icon-btn mob-back" data-go="/connectbox">${I('arrow-left', 18)}</button>${av(m.id, 38)}<div><div style="font-weight:700">${m.name}</div><div class="faint" style="font-size:11.5px">${m.st === 'off' ? 'Last seen 2h ago' : 'Active now'}</div></div><div class="row" style="margin-left:auto;gap:2px"><button class="icon-btn" data-act="toast" data-msg="Calling…">${I('phone', 17)}</button><button class="icon-btn" data-act="toast" data-msg="Video call…">${I('video', 18)}</button><button class="icon-btn" data-menu="chat">${I('ellipsis-vertical', 17)}</button></div></div>
        <div class="msgs" id="msgs"><span class="day-sep">Today</span>${c.msgs.map(([w, t]) => `<div class="msg ${w === 'me' ? 'me' : ''}">${esc(t)}<span class="tm">10:4${Math.floor(Math.random() * 9)} pm</span></div>`).join('')}</div>
        <div class="composer"><button class="icon-btn" data-act="toast" data-msg="Attach a file">${I('paperclip', 18)}</button><input class="input" id="cmp" placeholder="Type a message…" data-enter="send" style="border-radius:var(--radius-full)"><button class="icon-btn" data-act="toast" data-msg="Emoji picker">${I('smile', 18)}</button><button class="btn primary" data-act="send" style="width:38px;padding:0">${I('send', 16)}</button></div></div></div>`;
  }
  ACTS.send = () => {
    const i = document.getElementById('cmp'); const v = i.value.trim(); if (!v) return; i.value = '';
    const box = document.getElementById('msgs'); const conv = D.convs.find((x) => x.id === activeConv); conv.msgs.push(['me', v]); conv.last = v;
    box.insertAdjacentHTML('beforeend', `<div class="msg me">${esc(v)}<span class="tm">now</span></div>`); box.scrollTop = 1e6;
    setTimeout(() => { box.insertAdjacentHTML('beforeend', `<div class="msg" id="typing"><span class="typing"><i></i><i></i><i></i></span></div>`); box.scrollTop = 1e6; }, 500);
    setTimeout(() => { document.getElementById('typing')?.remove(); const r = ['Haha sotti 😄', 'Okay, done!', 'Ektu pore janacchi', 'Thanks! 🙌'][Math.floor(Math.random() * 4)]; conv.msgs.push(['them', r]); box.insertAdjacentHTML('beforeend', `<div class="msg">${r}<span class="tm">now</span></div>`); box.scrollTop = 1e6; }, 1900);
  };
  ACTS['new-chat'] = () => modal({ title: 'New message', icon: 'square-pen', body: `<input class="input" placeholder="Search people…"><div class="list">${D.members.slice(0, 5).map((m) => `<div class="list-row" data-act="go:/connectbox/c1" style="cursor:pointer">${av(m.id, 34)}<div class="grow"><div class="t">${m.name}</div><div class="s">${m.dept} · ${m.batch}</div></div></div>`).join('')}</div>`, foot: false });
  MENUS.chat = [['user', 'View profile', '', 'go:/members/m1'], ['bell', 'Mute'], ['image', 'Shared media'], ['trash-2', 'Delete chat', 'danger']];
  register({ path: '/connectbox', title: 'ConnectBox', group: 'Social', icon: 'message-square', render: connectbox, mount: () => { const b = document.getElementById('msgs'); if (b) b.scrollTop = 1e6; } });

  /* ───────────── Settings ───────────── */
  const STABS = [{ id: 'profile', label: 'Profile', icon: 'user' }, { id: 'appearance', label: 'Appearance', icon: 'palette' }, { id: 'notifications', label: 'Notifications', icon: 'bell' }, { id: 'accounts', label: 'Accounts', icon: 'shield-check' }, { id: 'about', label: 'About', icon: 'info' }];
  const THEMES = ['Dark', 'Light', 'Midnight', 'Nexus', 'Cyberpunk', 'Terminal', 'Art Deco', 'Bold Type', 'Newsprint', 'Sketchbook', 'Swiss', 'Blueprint'];
  function settings(sub) {
    sub = sub || 'profile'; let b = '';
    if (sub === 'profile') b = `<div class="main-grid"><section class="card"><div class="card-h"><h3>${I('user', 16)}Identity</h3></div><div class="row" style="gap:16px;margin-bottom:16px">${av('me', 72, false)}<div><b style="font-size:17px">${D.me.name}</b><div class="faint" style="font-size:12px">${D.me.sid} · ${D.me.dept} · Batch ${D.me.batch}</div><button class="btn sm" style="margin-top:8px" data-act="toast" data-msg="Photo picker opened">${I('upload', 13)}Change photo</button></div></div>
      <div class="form-grid"><div class="field"><span class="label">Full name</span><input class="input" value="${D.me.name}"></div><div class="field"><span class="label">Nickname</span><input class="input" value="Ahin"></div><div class="field"><span class="label">Department</span><select class="input"><option>CSE</option><option>EEE</option></select></div><div class="field"><span class="label">Semester</span><select class="input"><option>Year 3 - Semester 2</option></select></div><div class="field" style="grid-column:1/-1"><span class="label">Bio</span><textarea class="input">Building AUSTWise ✨</textarea></div></div>
      <div class="row" style="justify-content:flex-end;margin-top:14px"><button class="btn primary" data-act="toast" data-msg="Profile saved">Save changes</button></div></section>
      <div class="stack">${card('Privacy', 'lock', toggles([['Show me in Active Members', true], ['Show CGPA on profile', false], ['Allow DMs from anyone', true]]))}${card('Danger zone', 'triangle-alert', `<button class="btn danger" data-act="toast" data-msg="Confirmation needed" style="width:100%">${I('trash-2', 14)}Delete account</button>`)}</div></div>`;
    else if (sub === 'appearance') b = `<section class="card"><div class="card-h"><h3>${I('palette', 16)}Theme</h3><div class="r faint" style="font-size:12px">15 variants</div></div><div class="grid g4 keep2">${THEMES.map((t, i) => `<div class="theme-tile ${i === 0 ? 'on' : ''}" data-act="pick-theme" data-t="${t}"><div class="sw sw${i % 6}"><i></i><i></i><i></i></div><b>${t}</b></div>`).join('')}</div></section>${card('Layout', 'layout-grid', toggles([['Compact sidebar', false], ['Reduce motion', false], ['Show Pomodoro in navbar', true]]))}`;
    else if (sub === 'notifications') b = card('Notifications', 'bell', toggles([['Notice Board posts', true], ['Deadline reminders (24h before)', true], ['ConnectBox messages', true], ['Community mentions', false], ['Weekly summary email', false]]));
    else if (sub === 'accounts') b = card('Linked accounts', 'shield-check', `<div class="list">${[['Google', 'mubasshir@gmail.com', true], ['AUST Portal', D.me.sid, true], ['GitHub', 'Not linked', false]].map(([a, s, on]) => `<div class="list-row"><span class="ic-tile">${I(a === 'GitHub' ? 'code' : 'globe', 16)}</span><div class="grow"><div class="t">${a}</div><div class="s">${s}</div></div><button class="btn sm ${on ? '' : 'primary'}" data-act="toast" data-msg="${on ? 'Unlinked' : 'Linked'}">${on ? 'Unlink' : 'Link'}</button></div>`).join('')}</div>`);
    else b = card('About AUSTWise', 'info', `<p class="muted" style="margin:0 0 12px;line-height:1.6">Your all-in-one campus companion for AUST — routine, grades, resources, community and more.</p><div class="grid g3"><div><span class="label">Version</span><div class="num">4.12.0</div></div><div><span class="label">Features</span><div class="num">40+</div></div><div><span class="label">Themes</span><div class="num">15</div></div></div><div class="dashed"></div><div class="row wrap">${['Terms', 'Privacy', 'Cookies', 'Changelog', 'Feedback'].map((x) => `<a class="btn sm" data-go="/p/${x.toLowerCase()}">${x}</a>`).join('')}</div>`);
    return P.masthead({ icon: 'settings', over: 'Account', title: 'Settings', sub: 'Profile, look & feel, notifications', stats: [['Theme', 'Dark'], ['Linked', '2']] }) + tabs('/settings', STABS, sub) + b;
  }
  const toggles = (list) => `<div class="list">${list.map(([l, on]) => `<div class="list-row"><div class="grow t" style="font-weight:500">${l}</div><span class="switch ${on ? 'on' : ''}" data-act="sw"></span></div>`).join('')}</div>`;
  P.toggles = toggles;
  ACTS.sw = (el) => el.classList.toggle('on');
  ACTS['pick-theme'] = (el) => { document.querySelectorAll('.theme-tile').forEach((x) => x.classList.toggle('on', x === el)); const t = el.dataset.t; if (t === 'Dark' || t === 'Light') { document.documentElement.dataset.theme = t.toLowerCase(); parent.postMessage({ type: 'proto-theme', theme: t.toLowerCase() }, '*'); } toast(`${t} theme applied`); };
  register({ path: '/settings', title: 'Settings', group: 'Account', icon: 'settings', render: settings });

  /* ───────────── Member profile ───────────── */
  register({ path: '/members', title: 'Member Profile', group: 'Social', icon: 'user', hidden: true, nav: '/community', render: (id) => {
    const m = member(id || 'm1') || member('m1');
    return `<section class="card profile-top"><div class="row" style="gap:18px;flex-wrap:wrap">${av(m.id, 88)}<div style="flex:1;min-width:200px"><span class="label">${m.dept} · Batch ${m.batch}</span><h1 style="margin:4px 0;font-size:1.6rem;letter-spacing:-.02em">${m.name}</h1><div class="muted">${esc(m.bio || '')}</div><div class="row wrap" style="margin-top:10px"><span class="chip amber">${m.role}</span><span class="chip">${I('flame', 12)}${m.streak || 20} day streak</span></div></div><div class="row"><button class="btn primary" data-go="/connectbox/c1">${I('message-square', 15)}Message</button><button class="btn" data-act="toast" data-msg="Following">${I('user-plus', 15)}Follow</button></div></div></section>
      <div class="grid g4 keep2">${statCard('Contributions', '128', 'Notes, posts & answers', 'layers')}${statCard('Upvotes', '1.4k', 'Across Austeddit', 'thumbs-up', 'green')}${statCard('Resources', '23', 'Shared to Vault', 'book-open', 'cyan')}${statCard('Rank', '#14', 'In batch leaderboard', 'trophy')}</div>
      ${card('Recent activity', 'activity', `<div class="list">${D.posts.slice(0, 3).map((p) => `<div class="list-row" data-go="/austeddit" style="cursor:pointer"><span class="ic-tile">${I('message-circle', 15)}</span><div class="grow"><div class="t">${esc(p.title)}</div><div class="s">r/${p.sub} · ${p.time}</div></div><span class="faint">${I('arrow-up', 14)}</span><b>${p.up}</b></div>`).join('')}</div>`)}`;
  } });

  /* ───────────── Admin panel ───────────── */
  const ATABS = [{ id: 'overview', label: 'Overview', icon: 'eye' }, { id: 'users', label: 'Users', icon: 'users' }, { id: 'applications', label: 'Applications', icon: 'file-text' }, { id: 'notice', label: 'Notice Board', icon: 'megaphone' }, { id: 'canteen', label: 'Canteen', icon: 'utensils' }, { id: 'access', label: 'Access', icon: 'shield' }];
  register({ path: '/admin-panel', title: 'Admin Panel', group: 'Account', icon: 'shield', render: (sub) => {
    sub = sub || 'overview'; let b;
    if (sub === 'overview') b = `<div class="grid g4 keep2">${statCard('Total users', '8,412', `<span class="good">${I('trending-up', 13)}+214</span> this week`, 'users')}${statCard('Active now', '612', 'Peak 1,204 today', 'activity', 'green')}${statCard('Pending apps', '17', 'CR/SR & clubs', 'file-text', 'rose')}${statCard('Reports', '3', 'Needs review', 'flag', 'cyan')}</div>${card('Signups (last 14 days)', 'chart-column', `<div class="bars">${[30, 42, 38, 55, 61, 48, 70, 66, 80, 74, 92, 88, 101, 96].map((v) => `<i style="height:${v}%" title="${v * 3}"></i>`).join('')}</div>`)}`;
    else if (sub === 'users') b = `<section class="card"><div class="row between wrap" style="margin-bottom:12px"><input class="input" placeholder="Search users…" style="max-width:280px">${seg('urole', ['All', 'Students', 'Faculty', 'Admins'], 'All')}</div><div class="tscroll"><table class="table"><thead><tr><th>User</th><th>Dept</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${D.members.map((m) => `<tr><td><div class="row">${av(m.id, 30)}<b>${m.name}</b></div></td><td>${m.dept}</td><td><span class="chip">${m.role}</span></td><td>${m.st === 'off' ? '<span class="chip">Offline</span>' : '<span class="chip green">Active</span>'}</td><td><button class="icon-btn" data-menu="user-admin">${I('ellipsis-vertical', 16)}</button></td></tr>`).join('')}</tbody></table></div></section>`;
    else b = `<section class="card">${empty(ATABS.find((t) => t.id === sub)?.icon || 'inbox', 'Nothing to review', 'New items for this section show up here.', `<button class="btn primary sm" data-act="toast" data-msg="Refreshed">${I('refresh-cw', 14)}Refresh</button>`)}</section>`;
    return P.masthead({ icon: 'shield', over: 'Control', title: 'Admin Panel', sub: 'Users, content and access', stats: [['Users', '8.4k'], ['Pending', '17', true], ['Reports', '3']], menu: 'admin' }) + tabs('/admin-panel', ATABS, sub) + b;
  } });
  MENUS['user-admin'] = [['eye', 'View profile', '', 'go:/members/m1'], ['shield', 'Change role'], ['lock', 'Suspend', 'danger']];
})();
